import{c as a,Q as r,j as l,m as o}from"./chunks/framework.rWdQudnF.js";const g=JSON.parse('{"title":"数据流风格","description":"","frontmatter":{"title":"数据流风格"},"headers":[],"relativePath":"综合知识/架构设计/架构风格与模式/数据流风格.md","filePath":"综合知识/架构设计/架构风格与模式/数据流风格.md","lastUpdated":null}'),e={name:"综合知识/架构设计/架构风格与模式/数据流风格.md"};function i(n,t,d,s,h,u){return r(),l("div",null,[...t[0]||(t[0]=[o('<blockquote><p>数据流风格的核心：<strong>数据按从前向后的顺序流动加工</strong>，各个构件沿数据流方向执行。</p></blockquote><h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[ ] 批处理序列（整体传递，前后不关联）</li><li>[ ] 管道-过滤器（前输出 → 后输入）</li><li>[ ] 二者区别（关键考点）</li><li>[ ] 典型应用场景（传统编译器）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="批处理序列" tabindex="-1">批处理序列 <a class="header-anchor" href="#批处理序列" aria-label="Permalink to &quot;批处理序列&quot;">​</a></h3><ul><li>构件为一系列固定顺序的计算单元，构件之间<strong>只通过数据传递交互</strong></li><li>每个处理步骤是独立程序，<strong>每一步必须在前一步结束后才能开始</strong></li><li>数据必须是完整的，以<strong>整体</strong>方式传递</li><li>前后构件不一定有关联</li></ul><h3 id="管道-过滤器" tabindex="-1">管道-过滤器 <a class="header-anchor" href="#管道-过滤器" aria-label="Permalink to &quot;管道-过滤器&quot;">​</a></h3><ul><li>每个构件有一组输入输出，读取输入数据流，处理后产生输出数据流</li><li><strong>前一个构件的输出作为后一个构件的输入</strong>，前后数据流关联</li><li>过滤器 = 构件，管道 = 连接件</li><li>早期编译器采用此风格</li></ul><h3 id="🎯-二者核心区别-高频考点" tabindex="-1">🎯 二者核心区别（高频考点） <a class="header-anchor" href="#🎯-二者核心区别-高频考点" aria-label="Permalink to &quot;🎯 二者核心区别（高频考点）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>批处理</th><th>管道-过滤器</th></tr></thead><tbody><tr><td>前后关联</td><td>不一定关联</td><td><strong>前输出 = 后输入</strong></td></tr><tr><td>传递方式</td><td>以<strong>整体</strong>为单位</td><td><strong>增量流式</strong>传递</td></tr><tr><td>开始条件</td><td>前一步<strong>完全结束</strong></td><td>前一步<strong>执行到部分</strong>即可开始</td></tr><tr><td>典型用例</td><td>—</td><td>传统编译器</td></tr></tbody></table><h3 id="典型考题" tabindex="-1">典型考题 <a class="header-anchor" href="#典型考题" aria-label="Permalink to &quot;典型考题&quot;">​</a></h3><ul><li>传统编译器 → <strong>管道-过滤器</strong>（词法→语法→语义→代码生成，结果逐阶段传递）</li><li>数据处理软件（分步解析处理） → <strong>管道/过滤器</strong></li><li>气象数据清洗转换 → <strong>数据流风格</strong></li></ul>',12)])])}const _=a(e,[["render",i]]);export{g as __pageData,_ as default};
